"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["77062"],{44669(e){e.exports=JSON.parse('{"id":"V4-211","slug":"authorised-push-payment-fraud","term":"Authorised Push Payment Fraud","also_known_as":[],"difficulty":"Intermediate","definition":"Authorised push payment (APP) fraud is a type of fraud in which criminals trick a person into willingly sending money from their own bank account to an account controlled by the fraudster.","explanation":["The term is used mainly in the United Kingdom. Unlike unauthorised fraud, where a criminal takes money without permission, in APP fraud the victim authorises the payment themselves, believing it to be genuine.","Common types include purchase scams, where goods are paid for but never delivered; investment scams; romance scams; impersonation scams, where fraudsters pretend to be from a bank, police or tax authority and persuade victims to move money to a so-called safe account; and invoice scams, where fraudsters intercept or fake invoices to redirect payments.","For example, a person receives a call from someone claiming to be from their bank\u2019s fraud team, warning that their account has been compromised and instructing them to transfer their savings to a new account, which is actually controlled by the fraudster.","Historically, victims often struggled to get their money back, because they had authorised the payments. Since October 2024, UK rules require payment firms to reimburse most victims of APP fraud through Faster Payments, up to a maximum amount, with the cost shared between the sending and receiving firms. Other countries, such as Australia, have introduced or are developing their own scam protection frameworks."],"note":"","total":1725,"prev":{"slug":"austerity","term":"Austerity"},"next":{"slug":"authorized-shares","term":"Authorized Shares"}}')}}]);